const projects=[["egypt-airport","Airport & Duty Free — Egypt","3D visualization: Samir El Khoury."],["chalet","Laklouk Resort — Lebanon",""],["restaurant","The Nice Guy Restaurant — Dubai",""],["green-bath","Private Residence — Malta","Project credit: Arcrea Studio — Rony Bou Farhat. 3D visualization: Samir El Khoury."],["contemporary","Private Residence — Greece",""],["garden-pool","Private Villa — Monaco",""],["stone-entry","Private Villa — Monaco",""],["modern-villa","10 Villas Project — Cyprus",""],["classic","Private Residence — Paris",""],["malta","Private Residence — Malta","Project credit: Arcrea Studio — Rony Bou Farhat. 3D visualization: Samir El Khoury."]];
const grid=document.getElementById('traditional');for(const [id,title,credit] of projects){const b=document.createElement('button');b.className='imagebutton';b.dataset.image=`assets/${id}.jpg`;const img=document.createElement('img');img.src=b.dataset.image;img.alt=title;img.loading='lazy';const p=document.createElement('p');p.textContent=title;b.append(img,p);if(credit){const s=document.createElement('small');s.textContent=credit;b.append(s);}grid.append(b);}
const modal=document.getElementById('lightbox');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{const im=b.querySelector('img');document.getElementById('fullimage').src=b.dataset.image;document.getElementById('fullimage').alt=im.alt;document.getElementById('caption').textContent=im.alt;modal.showModal();}));document.getElementById('close').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
